<div class="panel mb-3"><h5>Tambah / Edit <?=html_escape($title)?></h5><form method="post" action="<?=site_url('crud/save/'.$table)?>" class="row">
<input type="hidden" name="<?=$this->security->get_csrf_token_name()?>" value="<?=$this->security->get_csrf_hash()?>"><input type="hidden" name="id" id="row_id">
<?php foreach($columns as $c):?><div class="col-md-3 form-group"><label><?=ucwords(str_replace('_',' ',$c))?></label><input class="form-control" name="<?=$c?>" id="f_<?=$c?>" <?=in_array($c,array('start_date','end_date','started_at','ended_at'))?'type="datetime-local"':(in_array($c,array('budget','price','views','likes','comments','shares','target_views','viewers_peak','gmv','agency_id','creator_id'))?'type="number" step="any"':'type="text')?>></div><?php endforeach;?>
<div class="col-12"><button class="btn btn-pink">Simpan</button> <button type="reset" class="btn btn-secondary" onclick="document.getElementById('row_id').value=''">Reset</button></div></form></div>
<div class="panel"><h5>Daftar <?=html_escape($title)?></h5><div class="table-responsive"><table class="table table-darkish"><thead><tr><th>ID</th><?php foreach($columns as $c):?><th><?=ucwords(str_replace('_',' ',$c))?></th><?php endforeach;?><th>Aksi</th></tr></thead><tbody>
<?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><?php foreach($columns as $c):?><td><?=html_escape(isset($r[$c])?$r[$c]:'')?></td><?php endforeach;?><td><button class="btn btn-sm btn-outline-info" onclick='editRow(<?=json_encode($r,JSON_HEX_APOS|JSON_HEX_QUOT)?>)'>Edit</button> <a class="btn btn-sm btn-outline-danger" onclick="return confirm('Hapus data ini?')" href="<?=site_url('crud/delete/'.$table.'/'.$r['id'])?>">Hapus</a></td></tr><?php endforeach;?>
<?php if(!$rows):?><tr><td colspan="<?=count($columns)+2?>" class="text-center muted">Belum ada data.</td></tr><?php endif;?></tbody></table></div></div>
<script>function editRow(r){document.getElementById('row_id').value=r.id;<?php foreach($columns as $c):?>document.getElementById('f_<?=$c?>').value=r.<?=$c?>||'';<?php endforeach;?>window.scrollTo({top:0,behavior:'smooth'});}</script>
